+/// The same, with `parent` as the config the definition is resolved against
+/// and `extra` laid over the child's environment.
+fn spawn_under(env: &Env, parent: &Config, def: &AgentDef, extra: &[(&str, &str)]) -> (Child, std::path::PathBuf) {
+    let cfg = parent.clone();
     let table = Catalog::build(&cfg.tools, None).unwrap().table();
     let cfg = def.child_config("scout", &cfg, &table).unwrap();
