 }

+/// The child reads its key with no fallback, so a parent must hand it the
+/// value the parent resolved under the name the child reads. Without that
+/// handoff (here: only `OPENROUTER_API_KEY` in its environment) it refuses to
+/// start rather than send an unauthenticated request.
+#[test]
+fn a_child_reads_only_the_secret_name_its_config_names() {
+    let env = Env::new("child-openrouter-key", json!({ "steps": [{ "text": "never" }] }));
+    let parent = Config { base_url: format!("http://127.0.0.1:{}/v1", env.port), ..Default::default() };
+    let (child, _) = spawn_under(
+        &env,
+        &parent,
+        &AgentDef::default(),
+        &[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "openrouter-KEY")],
+    );
+    let (ok, stderr) = ended(child);
+    assert!(!ok, "the child never started a turn");
+    assert!(stderr.contains("no API key: set OPENAI_API_KEY or OPENROUTER_API_KEY"), "{stderr}");
+    assert!(env.requests().is_empty(), "nothing was sent");
+}
+
+/// No key anywhere: the child fails with the reason, before any request.
+#[test]
+fn a_child_with_no_key_fails_before_a_request_and_says_which_key_to_set() {
+    let env = Env::new("child-no-key", json!({ "steps": [{ "text": "never" }] }));
+    let parent = Config { base_url: format!("http://127.0.0.1:{}/v1", env.port), ..Default::default() };
+    let (child, _) =
+        spawn_under(&env, &parent, &AgentDef::default(), &[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "")]);
+    let (ok, stderr) = ended(child);
+    assert!(!ok, "the child never started a turn");
+    assert!(stderr.contains("no API key: set OPENAI_API_KEY or OPENROUTER_API_KEY"), "{stderr}");
+    assert!(env.requests().is_empty(), "nothing was sent");
+}
+
+/// A child that gets no start line it can build a session from exits with the
+/// reason on stderr; returns whether it exited successfully and that stderr.
+fn ended(mut child: Child) -> (bool, String) {
+    let mut stderr = String::new();
+    child.stderr.take().unwrap().read_to_string(&mut stderr).unwrap();
+    let status = child.wait().unwrap();
+    (status.success(), stderr)
+}
+
+/// An endpoint explicitly keyless (`api_key_secret = ""`) needs no key, so
+/// the child runs unauthenticated instead of refusing to start.
+#[test]
+fn a_child_on_a_keyless_endpoint_runs_without_a_key() {
+    let env = Env::new("child-keyless", json!({ "steps": [{ "text": "found it" }] }));
+    let parent = Config {
+        base_url: format!("http://127.0.0.1:{}/v1", env.port),
+        api_key_secret: String::new(),
+        ..Default::default()
+    };
+    let (mut child, _) = spawn_under(&env, &parent, &AgentDef::default(), &[("OPENAI_API_KEY", "")]);
+    let mut wire = Wire::new(&mut child);
+    send(&mut child, &ToChild::Prompt { text: "go".into() });
+    assert!(!wire.turn_end());
+    drop(child.stdin.take());
+    wire.finish();
+    assert!(child.wait().unwrap().success());
+    let log = std::fs::read_to_string(env.dir.join("log.jsonl")).unwrap();
+    let auth: Vec<Value> = log.lines().map(|l| serde_json::from_str::<Value>(l).unwrap()["auth"].clone()).collect();
+    assert_eq!(auth, vec![Value::Null], "no Authorization header");
+}
+
