+/// With only `OPENROUTER_API_KEY` set, the parent resolves its key through the
+/// fallback; a child on the same endpoint must be handed that same key under
+/// the name it reads, not an empty one (issue #65).
+#[test]
+fn a_child_on_the_parents_endpoint_gets_the_key_the_parent_used() {
+    let env = Env::new(
+        "delegate-key-openrouter",
+        json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }),
+    );
+    env.config(&agent_config(&env, ""));
+    let out =
+        env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "openrouter-KEY")], &["run", "--no-learn", "go"]);
+    assert!(out.status.success(), "{}", text(&out));
+    // Parent, child, parent: every request carries the key the parent resolved.
+    assert_eq!(auth_seen(&env), vec![json!("Bearer open…"); 3]);
+}
+
+/// An endpoint explicitly configured as keyless (`api_key_secret = ""`) still
+/// runs, in the parent and in a child on the same endpoint, and never borrows
+/// a key that happens to be set.
+#[test]
+fn a_keyless_endpoint_runs_with_no_auth_in_the_parent_and_the_child() {
+    let env =
+        Env::new("delegate-keyless", json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }));
+    env.config(&format!("api_key_secret = \"\"\n{}", agent_config(&env, "")));
+    let out =
+        env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "openrouter-KEY")], &["run", "--no-learn", "go"]);
+    assert!(out.status.success(), "{}", text(&out));
+    assert_eq!(auth_seen(&env), vec![Value::Null; 3], "a keyless endpoint never borrows a key");
+}
+
+/// No key at all: the failure names the key to set before any request, rather
+/// than sending an unauthenticated request and showing the provider's 401.
+#[test]
+fn no_key_fails_before_a_request_and_says_which_key_to_set() {
+    let env = Env::new("delegate-no-key", json!({ "steps": [delegate("hi"), { "text": "hello" }] }));
+    env.config(&agent_config(&env, ""));
+    let out = env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "")], &["run", "--no-learn", "go"]);
+    assert!(!out.status.success(), "{}", text(&out));
+    assert!(text(&out).contains("no API key: set OPENAI_API_KEY or OPENROUTER_API_KEY"), "{}", text(&out));
+    assert!(env.requests().is_empty(), "nothing was sent");
+}
