+/// One secret for the child's environment. A child that inherits the parent's
+/// endpoint gets the key the parent actually used, under the name it reads:
+/// `OPENAI_API_KEY` may resolve only through the `OPENROUTER_API_KEY` fallback,
+/// and the child reads its own key with no fallback.
+fn secret_value(spec: &Spec<'_>, name: &str) -> Option<String> {
+    if spec.def.shares_endpoint(spec.parent) && name == spec.def.key_secret(spec.parent) {
+        return crate::secrets::api_key(&spec.parent.api_key_secret);
+    }
+    crate::secrets::get(name)
+}
+
