+/// The environment a child is given: only the secrets its definition names,
+/// plus its endpoint key. A child on the parent's endpoint is handed the key
+/// the parent actually used (the configured secret or the `OPENROUTER_API_KEY`
+/// fallback), under the name its own config reads. A key it names but cannot
+/// get is an error here, before the child starts, rather than an
+/// unauthenticated request and the provider's 401.
+fn child_env(spec: &Spec<'_>) -> anyhow::Result<Vec<(String, String)>> {
+    let key = spec.config.api_key_secret.as_str();
+    let mut env = vec![];
+    for name in spec.def.secret_names(spec.parent) {
+        let value = if name == key && spec.def.inherits_key() {
+            crate::secrets::api_key(&spec.parent.api_key_secret)?.map(|k| k.value)
+        } else {
+            crate::secrets::get(&name)
+        };
+        if let Some(v) = value {
+            env.push((name, v));
+        }
+    }
+    if !key.is_empty() && !env.iter().any(|(n, _)| n == key) && spec.def.command.is_empty() {
+        // The same words the parent gives for its own key: a delegation must
+        // not turn a missing key into the provider's 401. Another vendor's
+        // agent makes its own requests, so its key is left to it.
+        return Err(crate::secrets::no_api_key(key));
+    }
+    Ok(env)
+}
